SELECT
        id,
        garment_code,
        operation_type,
        operator_id,
        location_id,
        remark,
        create_time,
        update_time
FROM
    aioveu_laundry_garment_tracking


        AND id = #{queryParams.id}


        AND garment_code = #{queryParams.garmentCode}


        AND operation_type = #{queryParams.operationType}


        AND operator_id = #{queryParams.operatorId}


        AND location_id = #{queryParams.locationId}


        AND remark = #{queryParams.remark}
